<?php
require __DIR__.'/approval-integration.php';
$start=$count;$tag='exit-'.bin2hex(random_bytes(5));
$r=$master->call('users.php',['action'=>'create_company','name'=>'Partner exit QA','username'=>$tag,'email'=>$tag.'@example.test','password'=>'Test-passphrase-2026!','companyName'=>'Partner exit tests'],'POST');expect($r,200,'create isolated partner exit company');
$c=new TestClient();$c->login($tag);
$doc=['projects'=>[['id'=>'p','name'=>'Main project'],['id'=>'q','name'=>'Other project']],'projectPartners'=>[['id'=>'seller','projectId'=>'p','name'=>'Seller','sharePercentage'=>40,'currency'=>'USD','status'=>'active'],['id'=>'buyer','projectId'=>'p','name'=>'Existing buyer','sharePercentage'=>10,'currency'=>'USD','status'=>'active'],['id'=>'foreign','projectId'=>'q','name'=>'Foreign buyer','sharePercentage'=>0,'currency'=>'USD']],'projectInvestments'=>[['id'=>'capital','projectId'=>'p','partnerId'=>'seller','partnerName'=>'Seller','amount'=>100,'currency'=>'USD','date'=>TEST_DAY,'type'=>'initial','approvalStatus'=>'draft','approvalHistory'=>[]]]];expect($c->save($doc),200,'create partner capital draft');foreach(['submitted','approved','posted'] as $status)expect($c->transition('projectInvestments','capital',$status),200,'capital '.$status);
function saleDoc(TestClient $c,string $id,string $to,float $percent,string $type='partner_to_partner'):array{
 $d=$c->workspace()['document'];foreach($d['projectPartners'] as &$p){if($p['id']==='seller'){$p['sharePercentage']-=$percent;if($p['sharePercentage']==0){$p['status']='exited';$p['exitDate']=TEST_DAY;}}if($p['id']===$to)$p['sharePercentage']+=$percent;}unset($p);
 if($type==='new_partner')$d['projectPartners'][]=['id'=>$to,'projectId'=>'p','name'=>'New buyer','sharePercentage'=>$percent,'initialInvestment'=>0,'currency'=>'USD','status'=>'active'];
 $d['partnerEquityTransfers'][]=['id'=>$id,'projectId'=>'p','fromPartnerId'=>'seller','fromPartnerName'=>'Seller','toPartnerId'=>$to,'toPartnerName'=>$type==='new_partner'?'New buyer':'Existing buyer','transferredPercentage'=>$percent,'transferPrice'=>500,'currency'=>'USD','transferDate'=>TEST_DAY,'transferType'=>$type];return $d;
}
$bad=saleDoc($c,'bad-project','foreign',10);expect($c->save($bad),400,'share buyer from another project rejected');
$bad=saleDoc($c,'over-sale','buyer',41);expect($c->save($bad),400,'selling more than owned rejected');
$bad=$c->workspace()['document'];$bad['projectPartners'][0]['status']='exited';expect($c->save($bad),400,'cannot end partnership while shares remain');
$bad=saleDoc($c,'bad-buyer','new',10,'new_partner');$bad['projectPartners'][3]['projectId']='q';expect($c->save($bad),400,'new buyer cannot be inserted into another project');
$bad=saleDoc($c,'bad-buyer','new',10,'new_partner');$bad['projectPartners'][3]['initialInvestment']=500;expect($c->save($bad),400,'private sale cannot manufacture initial company investment');
$bad=saleDoc($c,'bad-share','buyer',10);$bad['projectPartners'][1]['sharePercentage']=21;expect($c->save($bad),400,'buyer shares must reconcile exactly');
$s=staff($c,$tag.'-no-create',['equity'=>['view','create'],'partners'=>['view','edit']]);$bad=saleDoc($s,'no-create','worker-new',10,'new_partner');expect($s->save($bad),403,'new buyer requires explicit partner create permission');
$viewer=staff($c,$tag.'-viewer',['equity'=>['view'],'partners'=>['view']]);$bad=saleDoc($viewer,'no-transfer','buyer',10);expect($viewer->save($bad),403,'viewer cannot sell partner shares');
$before=$c->workspace()['document'];expect($c->save(saleDoc($c,'partial','new',10,'new_partner')),200,'partial sale creates buyer atomically');$now=$c->workspace()['document'];$map=array_column($now['projectPartners'],null,'id');check($map['seller']['sharePercentage']===30&&$map['new']['sharePercentage']===10,'partial sale preserves remainder and transfers exact share');check($now['projectInvestments']===$before['projectInvestments']&&empty($now['payments']),'private sale preserves posted capital and adds no company cash');
expect($c->save(saleDoc($c,'full','buyer',30)),200,'full sale ends partnership');$now=$c->workspace()['document'];$map=array_column($now['projectPartners'],null,'id');check($map['seller']['status']==='exited'&&$map['seller']['sharePercentage']===0&&$map['buyer']['sharePercentage']===40,'exit status and shares persist');check($now['projectInvestments']===$before['projectInvestments']&&count($now['partnerEquityTransfers'])===2,'capital and both share history records preserved');
$bad=$now;$bad['partnerEquityTransfers'][0]['transferPrice']=1;expect($c->save($bad),409,'share sale cannot be rewritten');$bad=$now;$bad['partnerEquityTransfers']=[];expect($c->save($bad),409,'share sale cannot be deleted');$bad=$now;$bad['projectPartners']=array_values(array_filter($bad['projectPartners'],fn($p)=>$p['id']!=='new'));expect($c->save($bad),409,'partner involved in share history cannot be deleted');
echo 'PARTNER EXIT '.($count-$start)." CHECKS PASSED; TOTAL $count\n";
